:root {
  --bg: #f5f6f8;
  --card: #ffffff;
  --border: #e2e5ea;
  --text: #1c2330;
  --muted: #6b7280;
  --accent: #2563eb;
  --accent-hover: #1d4ed8;
  --danger: #dc2626;
  --warn-bg: #fef3c7;
  --warn-text: #92400e;
}

* { box-sizing: border-box; }

body {
  margin: 0;
  font-family: system-ui, -apple-system, Segoe UI, Roboto, sans-serif;
  background: var(--bg);
  color: var(--text);
}

.topbar {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 1rem 1.5rem;
  background: var(--card);
  border-bottom: 1px solid var(--border);
}
.topbar h1 { font-size: 1.25rem; margin: 0; }

.container { max-width: 800px; margin: 0 auto; padding: 1.5rem; }

.controls { margin-bottom: 1.25rem; }
#search {
  width: 100%;
  padding: 0.65rem 0.85rem;
  font-size: 1rem;
  border: 1px solid var(--border);
  border-radius: 8px;
}

.tag-filters {
  display: flex;
  flex-wrap: wrap;
  gap: 0.4rem;
  margin-top: 0.75rem;
}
.tag-chip {
  padding: 0.25rem 0.7rem;
  border: 1px solid var(--border);
  border-radius: 999px;
  background: var(--card);
  cursor: pointer;
  font-size: 0.85rem;
  color: var(--muted);
}
.tag-chip.active {
  background: var(--accent);
  color: #fff;
  border-color: var(--accent);
}

.list { display: flex; flex-direction: column; gap: 0.75rem; }

.bookmark {
  background: var(--card);
  border: 1px solid var(--border);
  border-radius: 10px;
  padding: 0.9rem 1rem;
}
.bookmark a.title {
  font-size: 1.05rem;
  font-weight: 600;
  color: var(--accent);
  text-decoration: none;
  word-break: break-word;
}
.bookmark a.title:hover { text-decoration: underline; }
.bookmark .addr {
  display: block;
  font-size: 0.8rem;
  color: var(--muted);
  margin: 0.15rem 0 0.35rem;
  word-break: break-all;
}
.bookmark .note { margin: 0.35rem 0; font-size: 0.9rem; }
.bookmark .tags { display: flex; flex-wrap: wrap; gap: 0.35rem; margin-top: 0.5rem; }
.bookmark .tag {
  font-size: 0.75rem;
  background: #eef2ff;
  color: #3730a3;
  padding: 0.1rem 0.55rem;
  border-radius: 999px;
}
.bookmark .row-actions {
  margin-top: 0.6rem;
  display: flex;
  gap: 0.5rem;
}

.empty {
  text-align: center;
  color: var(--muted);
  padding: 3rem 1rem;
}

.btn {
  border: 1px solid var(--border);
  background: var(--card);
  color: var(--text);
  padding: 0.4rem 0.85rem;
  border-radius: 8px;
  cursor: pointer;
  font-size: 0.9rem;
}
.btn:hover { background: #f0f2f5; }
.btn.primary { background: var(--accent); color: #fff; border-color: var(--accent); }
.btn.primary:hover { background: var(--accent-hover); }
.btn.link { border: none; background: none; color: var(--accent); padding: 0.2rem; }
.btn.danger { color: var(--danger); border: none; background: none; }

