  const r = await list('?q=zzzznope');
  assert.deepEqual(r, []);
});

test('tags endpoint lists tags in use', async () => {
  const res = await fetch(base + '/api/tags');
  const { tags } = await res.json();
  assert.deepEqual(tags.sort(), ['reading', 'web']);
});

